def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the uniform separator between equal-sized panels, then mark
    # positions occupied (nonzero) in both panels.
    for r in range(h):
        if len(set(grid[r])) == 1 and r > 0 and h - r - 1 == r:
            top, bottom = grid[:r], grid[r + 1:]
            return [[2 if top[i][j] != 0 and bottom[i][j] != 0 else 0
                     for j in range(w)] for i in range(r)]
    for c in range(w):
        if all(row[c] == grid[0][c] for row in grid) and c > 0 and w - c - 1 == c:
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            return [[2 if left[i][j] != 0 and right[i][j] != 0 else 0
                     for j in range(c)] for i in range(h)]
    raise ValueError("No centered uniform separator with equal panels")
